import{_ as i,o as t,c as l,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2019-01-31 :: Ceph Performance meeting","description":"","frontmatter":{"title":"2019-01-31 :: Ceph Performance meeting","date":"2019-01-31T00:00:00.000Z","updated":"2019-02-05T00:00:00.000Z","tags":["Ceph性能","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-01-31_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-01-31_-_-_Ceph_Performance_meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-01-31_-_-_Ceph_Performance_meeting.md"};function s(a,e,o,p,g,c){return t(),l("div",null,[...e[0]||(e[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年[具体日期]</p><p><strong>参会人员</strong>： Sage, Ma Jian Pang, Cruising, Radek, Keefe, Braddock, Adam, Casey, Nick, Matt, French等</p><p><strong>会议主题</strong>：</p><ul><li>确认和讨论Ceph分布式存储项目中的最新进展和问题。</li><li>讨论Ceph在容器工作负载中的性能问题，特别是创建文件系统时的延迟。</li><li>探讨Ceph-RBD的性能和未来发展方向。</li></ul><p><strong>关键细节和讨论议题</strong>：</p><ul><li><strong>批量处理和发送消息工作</strong>： Ma Jian Pang的工作得到Sage的赞赏，并计划进行测试。</li><li><strong>memstore优化</strong>： Radek开发的Science Star变体旨在消除不必要的锁定和原子操作，并利用Crimson测试阶段的特性。与会者对此表示兴奋，并期待进一步进展。</li><li><strong>IObject集成</strong>： Adam将IObject集成到RGW中，以优化性能，并建议将RGW特定的更改拆分为单独的PR。</li><li><strong>性能问题</strong>： Nick报告了在创建文件系统时遇到的问题，特别是在使用XFS的情况下，与会者讨论了可能的解决方案，如将零填充转换为丢弃操作。</li><li><strong>Ceph-RBD性能</strong>： Nick正在重新编写FIO CBT基准测试，以简化测试过程并提高效率。与会者讨论了Ceph-RBD的不同实现，包括RBD fuse和TCM。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>Sage将尝试测试Ma Jian Pang的工作。</li><li>Radek将继续开发Science Star。</li><li>Adam将集成IObject到RGW。</li><li>Nick将重新编写FIO CBT基准测试。</li><li>讨论将关于操作和SMDs的讨论主题添加到下周会议议程。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sage、Radek、Adam和Nick将继续他们的工作。</li><li>将讨论操作和SMDs的议题添加到下周会议议程。</li><li>尝试使用其他文件系统（如ext4和XFS）来避免XFS的延迟问题。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了以下计算机科学/ceph相关领域英文关键词： <ul><li>batch handling</li><li>send message</li><li>memstore</li><li>crimson</li><li>science star</li><li>intrusive data structures</li><li>RGW</li><li>IObject</li><li>XFS</li><li>Ceph-RBD</li><li>FIO CBT benchmarks</li></ul></li></ul>",13)])])}const d=i(r,[["render",s]]);export{m as __pageData,d as default};
